import csv
from collections import Counter

counts = Counter()
with open('customers.csv', newline='') as f:
    reader = csv.DictReader(f)
    for row in reader:
        for k, v in row.items():
            if v is None or v.strip() == '':
                counts[k] += 1

for col, n in counts.most_common():
    print(f'{col}: {n}')

