import csv
from collections import Counter

counts = Counter()
total = 0
with open('responses.csv') as f:
    for row in csv.DictReader(f):
        total += 1
        for k, v in row.items():
            if v.strip():
                counts[k] += 1
for q, n in counts.items():
    print(q, n, f'{100*n/total:.1f}%')
